"""Forty-five concrete report contracts and SQL references per analysis profile."""
from domain_interview_focus import profile


def recipes():
    rows=[]
    def add(level,title,task,ctes,report,columns,order,edge):
        rows.append(dict(level=level,title=title,task=task,ctes=ctes,report=report,
                         columns=columns.split(','),order=order,edge=edge))
    b=lambda *args:add('Beginner',*args)
    i=lambda *args:add('Intermediate',*args)
    a=lambda *args:add('Advanced',*args)
    b('Analysis audit','Return every analysis row with its owner,date,value and segment.',[],
      'SELECT EventID,OwnerID,ActivityDate,MetricValue,Segment FROM E','EventID,OwnerID,ActivityDate,MetricValue,Segment','EventID','Keep null values and stored token spaces.')
    b('Known versus unknown','Return only analysis rows with a known value.',[],
      'SELECT EventID,OwnerID,MetricValue FROM E WHERE MetricValue IS NOT NULL','EventID,OwnerID,MetricValue','EventID','Known zero is not unknown.')
    b('Unknown-value queue','Return the IDs and dates of rows whose analysis value is unknown.',[],
      'SELECT EventID,ActivityDate FROM E WHERE MetricValue IS NULL','EventID,ActivityDate','EventID','An empty queue must have the requested columns.')
    b('Threshold review','Return known analysis values at least100.',[],
      'SELECT EventID,MetricValue FROM E WHERE MetricValue>=100','EventID,MetricValue','EventID','The lower bound is inclusive;unknown values cannot pass.')
    b('Deterministic shortlist','Return at most five rows by descending known analysis value,then ascending source ID;unknown values are excluded.',[],
      'SELECT TOP (5) EventID,MetricValue FROM E WHERE MetricValue IS NOT NULL ORDER BY MetricValue DESC,EventID','EventID,MetricValue','MetricValue DESC,EventID','Return fewer than five if fewer qualify;ties do not expand the result.')
    b('Active-owner totals','For each owner present in the analysis population,return row count,known-value count and sum of known values.',[],
      'SELECT OwnerID,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS TotalValue FROM E GROUP BY OwnerID','OwnerID,EventCount,KnownCount,TotalValue','OwnerID','An all-unknown owner has null total,not zero.')
    b('All-owner coverage','Return every master owner,including those with no eligible activity. Empty owners have count0,known count0,total0;an active all-unknown owner has null total.',
      [('T','SELECT OwnerID,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS TotalValue FROM E GROUP BY OwnerID')],
      'SELECT p.OwnerID,COALESCE(t.EventCount,0) AS EventCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.EventCount IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue FROM Owners p LEFT JOIN T t ON t.OwnerID=p.OwnerID','OwnerID,EventCount,KnownCount,TotalValue','OwnerID','Count real activity,not an outer-join placeholder.')
    b('Segment profile','Return each analysis segment with row count,known count and known-value sum.',[],
      'SELECT Segment,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS TotalValue FROM E GROUP BY Segment','Segment,EventCount,KnownCount,TotalValue','Segment','Use SQL Server collation equality for segment grouping.')
    b('Owner segment coverage','Return each distinct owner/segment pair exactly once.',[],
      'SELECT DISTINCT OwnerID,Segment FROM E','OwnerID,Segment','OwnerID,Segment','Repeated activity in one segment does not duplicate its owner/segment pair.')
    b('Observed-month totals','Return one row per calendar month present in the analysis population,with event count,known count and sum.',
      [('M','SELECT DATEFROMPARTS(YEAR(ActivityDate),MONTH(ActivityDate),1) AS MonthStart,MetricValue FROM E')],
      'SELECT MonthStart,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS TotalValue FROM M GROUP BY MonthStart','MonthStart,EventCount,KnownCount,TotalValue','MonthStart','Do not fabricate missing months in this question.')
    b('Daily workload','Return one row per owner/analysis date with count and known-value sum.',[],
      'SELECT OwnerID,ActivityDate,COUNT(*) AS EventCount,SUM(MetricValue) AS TotalValue FROM E GROUP BY OwnerID,ActivityDate','OwnerID,ActivityDate,EventCount,TotalValue','OwnerID,ActivityDate','Different source rows on the same day remain separate contributions.')
    b('No eligible activity','Return master owner IDs having no analysis rows.',[],
      'SELECT p.OwnerID FROM Owners p WHERE NOT EXISTS(SELECT 1 FROM E e WHERE e.OwnerID=p.OwnerID)','OwnerID','OwnerID','An owner with an unknown-value row is active.')
    b('Visible parent link','Return analysis row IDs whose parent is also an analysis row,and the parent ID and both values.',[],
      'SELECT c.EventID,c.ParentID,c.MetricValue AS ChildValue,p.MetricValue AS ParentValue FROM E c JOIN E p ON p.EventID=c.ParentID','EventID,ParentID,ChildValue,ParentValue','EventID','A parent excluded by the analysis eligibility rule is not visible here.')
    b('Bounded-value counts','For every observed segment,return total rows and count of known values in the inclusive interval[100,200].',[],
      'SELECT Segment,COUNT(*) AS EventCount,SUM(CASE WHEN MetricValue BETWEEN 100 AND 200 THEN 1 ELSE 0 END) AS InRangeCount FROM E GROUP BY Segment','Segment,EventCount,InRangeCount','Segment','Return0 for a segment with no values in the interval.')
    b('Value sign reconciliation','Return one summary row splitting all analysis rows into unknown,negative,zero and positive counts.',[],
      'SELECT COUNT(*) AS EventCount,COUNT(*)-COUNT(MetricValue) AS UnknownCount,COALESCE(SUM(CASE WHEN MetricValue<0 THEN 1 ELSE 0 END),0) AS NegativeCount,COALESCE(SUM(CASE WHEN MetricValue=0 THEN 1 ELSE 0 END),0) AS ZeroCount,COALESCE(SUM(CASE WHEN MetricValue>0 THEN 1 ELSE 0 END),0) AS PositiveCount FROM E','EventCount,UnknownCount,NegativeCount,ZeroCount,PositiveCount','EventCount','All four classes must sum to EventCount;empty input returns five zero counts.')

    i('Exactly two per owner','Return up to two known-value rows per owner ordered by value descending then source ID ascending. Keep the position1 or2.',
      [('R','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY MetricValue DESC,EventID) AS Position FROM E WHERE MetricValue IS NOT NULL')],
      'SELECT OwnerID,EventID,MetricValue,Position FROM R WHERE Position<=2','OwnerID,EventID,MetricValue,Position','OwnerID,Position','Ties cannot expand a two-row limit.')
    i('Two value positions with ties','Return all rows in each owner\'s two highest distinct known analysis values. Return ValueRank.',
      [('R','SELECT *,DENSE_RANK() OVER(PARTITION BY OwnerID ORDER BY MetricValue DESC) AS ValueRank FROM E WHERE MetricValue IS NOT NULL')],
      'SELECT OwnerID,EventID,MetricValue,ValueRank FROM R WHERE ValueRank<=2','OwnerID,EventID,MetricValue,ValueRank','OwnerID,ValueRank,EventID','Several rows may share rank2;all must remain.')
    i('Running value and knowledge','For each row,return the running known-value sum and known count through that row within its owner,ordered by date then source ID.',[],
      'SELECT EventID,OwnerID,ActivityDate,MetricValue,SUM(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS RunningValue,COUNT(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS RunningKnownCount FROM E','EventID,OwnerID,ActivityDate,MetricValue,RunningValue,RunningKnownCount','OwnerID,ActivityDate,EventID','An all-unknown prefix has null RunningValue.')
    i('Previous row delta','Return each row\'s immediately preceding analysis value within its owner,date/source-ID order,and current-minus-previous.',
      [('P','SELECT *,LAG(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID) AS PreviousValue FROM E')],
      'SELECT EventID,OwnerID,MetricValue,PreviousValue,MetricValue-PreviousValue AS Delta FROM P','EventID,OwnerID,MetricValue,PreviousValue,Delta','OwnerID,EventID','Do not skip an unknown predecessor.')
    i('Share before filtering','Sum only positive analysis values per segment/owner. Return the top two distinct owner totals per segment,including all ties,and each owner\'s percentage of the complete segment total before filtering.',
      [('T','SELECT Segment,OwnerID,SUM(MetricValue) AS TotalValue FROM E WHERE MetricValue>0 GROUP BY Segment,OwnerID'),('R','SELECT *,DENSE_RANK() OVER(PARTITION BY Segment ORDER BY TotalValue DESC) AS ValueRank,SUM(TotalValue) OVER(PARTITION BY Segment) AS SegmentTotal FROM T')],
      'SELECT Segment,OwnerID,TotalValue,ValueRank,SegmentTotal,CAST(100.0*TotalValue/NULLIF(SegmentTotal,0) AS decimal(19,6)) AS SharePercent FROM R WHERE ValueRank<=2','Segment,OwnerID,TotalValue,ValueRank,SegmentTotal,SharePercent','Segment,ValueRank,OwnerID','Filtered-out owners must still contribute to the denominator.')
    i('Every required segment','Return owners having at least one analysis row in each exact segment A,B,C,and their activity count and known total across all segments.',
      [('Required',"SELECT N'A' AS Segment UNION ALL SELECT N'B' UNION ALL SELECT N'C'"),('T','SELECT OwnerID,COUNT(*) AS EventCount,SUM(MetricValue) AS TotalValue FROM E GROUP BY OwnerID')],
      'SELECT t.OwnerID,t.EventCount,t.TotalValue FROM T t WHERE NOT EXISTS(SELECT 1 FROM Required r WHERE NOT EXISTS(SELECT 1 FROM E e WHERE e.OwnerID=t.OwnerID AND e.Segment=r.Segment))','OwnerID,EventCount,TotalValue','OwnerID','Unknown-value activity still proves coverage;an owner with no activity cannot cover a nonempty requirement list.')
    i('Prior calendar window','For every row,return count and average of known values for the same owner on dates from current date minus30 inclusive to current date exclusive.',[],
      'SELECT c.EventID,c.OwnerID,COUNT(p.MetricValue) AS PriorKnownCount,CAST(AVG(CAST(p.MetricValue AS decimal(28,6))) AS decimal(28,6)) AS PriorAverage FROM E c LEFT JOIN E p ON p.OwnerID=c.OwnerID AND p.ActivityDate>=DATEADD(day,-30,c.ActivityDate) AND p.ActivityDate<c.ActivityDate GROUP BY c.EventID,c.OwnerID','EventID,OwnerID,PriorKnownCount,PriorAverage','OwnerID,EventID','Exclude every same-day row,not just the current source ID;no known history gives count0 and null average.')
    i('First and last known rows','For each master owner,return first and last known-value source IDs by analysis date then source ID. Owners without known values have null IDs.',
      [('K','SELECT OwnerID,EventID,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID) AS FirstPos,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY ActivityDate DESC,EventID DESC) AS LastPos FROM E WHERE MetricValue IS NOT NULL')],
      'SELECT p.OwnerID,MAX(CASE WHEN k.FirstPos=1 THEN k.EventID END) AS FirstEventID,MAX(CASE WHEN k.LastPos=1 THEN k.EventID END) AS LastEventID FROM Owners p LEFT JOIN K k ON k.OwnerID=p.OwnerID GROUP BY p.OwnerID','OwnerID,FirstEventID,LastEventID','OwnerID','Known zero participates;do not independently take the minimum value instead of the first row.')
    i('Complete 2024 calendar','Return all12 calendar months of2024 for every master owner,with event/known counts and total. No activity means total0;an active all-unknown month means null.',
      [('Months',"SELECT CAST('20240101' AS date) AS MonthStart UNION ALL SELECT DATEADD(month,1,MonthStart) FROM Months WHERE MonthStart<'20241201'"),('T',"SELECT OwnerID,DATEFROMPARTS(YEAR(ActivityDate),MONTH(ActivityDate),1) AS MonthStart,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS TotalValue FROM E WHERE ActivityDate>='20240101' AND ActivityDate<'20250101' GROUP BY OwnerID,DATEFROMPARTS(YEAR(ActivityDate),MONTH(ActivityDate),1)")],
      'SELECT p.OwnerID,m.MonthStart,COALESCE(t.EventCount,0) AS EventCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.EventCount IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue FROM Owners p CROSS JOIN Months m LEFT JOIN T t ON t.OwnerID=p.OwnerID AND t.MonthStart=m.MonthStart','OwnerID,MonthStart,EventCount,KnownCount,TotalValue','OwnerID,MonthStart','Each owner has exactly12 rows;2025 activity cannot enter2024.')
    i('Dominant segments','Return every tied highest-known-total segment per owner. Exclude all-unknown segment groups;keep known zero or negative totals.',
      [('T','SELECT OwnerID,Segment,SUM(MetricValue) AS TotalValue FROM E GROUP BY OwnerID,Segment HAVING COUNT(MetricValue)>0'),('R','SELECT *,DENSE_RANK() OVER(PARTITION BY OwnerID ORDER BY TotalValue DESC) AS ValueRank FROM T')],
      'SELECT OwnerID,Segment,TotalValue FROM R WHERE ValueRank=1','OwnerID,Segment,TotalValue','OwnerID,Segment','The best of several negative totals is the least negative,not zero.')
    i('Same-day repeated values','Return owner/date/value groups occurring at least twice,including a repeated unknown value as one group. Return Multiplicity.',[],
      'SELECT OwnerID,ActivityDate,MetricValue,COUNT(*) AS Multiplicity FROM E GROUP BY OwnerID,ActivityDate,MetricValue HAVING COUNT(*)>=2','OwnerID,ActivityDate,MetricValue,Multiplicity','OwnerID,ActivityDate,MetricValue','Unknown-value groups are compared using grouping semantics rather than equality-to-null predicates.')
    i('First threshold crossing','Within each owner,consider positive values ordered by date/source ID. Return the first row where cumulative value reaches at least80 percent of that owner\'s complete positive total.',
      [('R','SELECT *,SUM(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS RunningValue,SUM(MetricValue) OVER(PARTITION BY OwnerID) AS TotalValue FROM E WHERE MetricValue>0'),('C','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID) AS Choice FROM R WHERE RunningValue>=0.8*TotalValue')],
      'SELECT OwnerID,EventID,RunningValue,TotalValue FROM C WHERE Choice=1','OwnerID,EventID,RunningValue,TotalValue','OwnerID','Owners with no positive values produce no threshold crossing.')
    i('Owner median','For every master owner,return the median known analysis value and KnownCount. Use the average of the two central values for an even count.',
      [('K','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY MetricValue,EventID) AS Position,COUNT(*) OVER(PARTITION BY OwnerID) AS KnownCount FROM E WHERE MetricValue IS NOT NULL'),('T','SELECT OwnerID,MAX(KnownCount) AS KnownCount,CAST(AVG(CAST(MetricValue AS decimal(28,6))) AS decimal(28,6)) AS MedianValue FROM K WHERE 2*Position BETWEEN KnownCount AND KnownCount+2 GROUP BY OwnerID')],
      'SELECT p.OwnerID,COALESCE(t.KnownCount,0) AS KnownCount,t.MedianValue FROM Owners p LEFT JOIN T t ON t.OwnerID=p.OwnerID','OwnerID,KnownCount,MedianValue','OwnerID','No known values gives count0 and null median,not zero.')
    i('Two-generation comparison','Return every analysis row with its visible parent and visible grandparent IDs and values;retain rows missing either ancestor.',[],
      'SELECT c.EventID,p.EventID AS ParentEventID,g.EventID AS GrandparentEventID,c.MetricValue,p.MetricValue AS ParentValue,g.MetricValue AS GrandparentValue FROM E c LEFT JOIN E p ON p.EventID=c.ParentID LEFT JOIN E g ON g.EventID=p.ParentID','EventID,ParentEventID,GrandparentEventID,MetricValue,ParentValue,GrandparentValue','EventID','Two joins cannot follow an excluded parent through to its grandparent.')
    i('Largest inactive gap','Deduplicate active dates per owner. Return its largest consecutive-active-date gap in calendar days,with start/end dates;ties choose earlier start. Include all owners with null gap if fewer than two active dates.',
      [('D','SELECT DISTINCT OwnerID,ActivityDate FROM E'),('L','SELECT OwnerID,ActivityDate AS EndDate,LAG(ActivityDate) OVER(PARTITION BY OwnerID ORDER BY ActivityDate) AS StartDate FROM D'),('R','SELECT *,DATEDIFF(day,StartDate,EndDate) AS GapDays,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY DATEDIFF(day,StartDate,EndDate) DESC,StartDate) AS Choice FROM L WHERE StartDate IS NOT NULL')],
      'SELECT p.OwnerID,r.StartDate,r.EndDate,r.GapDays FROM Owners p LEFT JOIN R r ON r.OwnerID=p.OwnerID AND r.Choice=1','OwnerID,StartDate,EndDate,GapDays','OwnerID','Multiple source rows on one day do not create a zero-day consecutive-date gap.')

    a('Session boundaries and comparable recovery','Within each owner,date/source-ID order,new activity starts a new session only when its calendar-date gap from the immediately preceding row exceeds30 days. Return each session\'s start/end,count,known count,total,previous-session total and percentage change. Include an inactive owner with SessionNo0,null dates,zero counts/total and null comparison.',
      [('L','SELECT *,LAG(ActivityDate) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID) AS PreviousDate FROM E'),('S','SELECT *,SUM(CASE WHEN PreviousDate IS NULL OR DATEDIFF(day,PreviousDate,ActivityDate)>30 THEN 1 ELSE 0 END) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS SessionNo FROM L'),('T','SELECT OwnerID,SessionNo,MIN(ActivityDate) AS StartDate,MAX(ActivityDate) AS EndDate,COUNT(*) AS EventCount,COUNT(MetricValue) AS KnownCount,CAST(SUM(MetricValue) AS decimal(28,4)) AS TotalValue FROM S GROUP BY OwnerID,SessionNo'),('P','SELECT *,LAG(TotalValue) OVER(PARTITION BY OwnerID ORDER BY SessionNo) AS PreviousValue FROM T')],
      'SELECT o.OwnerID,COALESCE(p.SessionNo,0) AS SessionNo,p.StartDate,p.EndDate,COALESCE(p.EventCount,0) AS EventCount,COALESCE(p.KnownCount,0) AS KnownCount,CASE WHEN p.SessionNo IS NULL THEN CAST(0 AS decimal(38,4)) ELSE p.TotalValue END AS TotalValue,p.PreviousValue,CAST(100.0*(p.TotalValue-p.PreviousValue)/NULLIF(p.PreviousValue,0) AS decimal(38,6)) AS GrowthPercent FROM Owners o LEFT JOIN P p ON p.OwnerID=o.OwnerID','OwnerID,SessionNo,StartDate,EndDate,EventCount,KnownCount,TotalValue,PreviousValue,GrowthPercent','OwnerID,SessionNo','A gap exactly30 remains in the session. Null or zero previous total gives null growth. Unknown rows still keep a session active.')
    a('Prior-window median anomaly','For every analysis row,find known values for the same owner over[current date-30,current date),calculate their exact median and count,and flag current value strictly greater than twice that median. Return every current row,not only anomalies.',
      [('H','SELECT c.EventID,p.EventID AS HistoryID,p.MetricValue,ROW_NUMBER() OVER(PARTITION BY c.EventID ORDER BY p.MetricValue,p.EventID) AS Position,COUNT(*) OVER(PARTITION BY c.EventID) AS KnownCount FROM E c JOIN E p ON p.OwnerID=c.OwnerID AND p.ActivityDate>=DATEADD(day,-30,c.ActivityDate) AND p.ActivityDate<c.ActivityDate WHERE p.MetricValue IS NOT NULL'),('M','SELECT EventID,MAX(KnownCount) AS KnownCount,CAST(AVG(CAST(MetricValue AS decimal(28,6))) AS decimal(28,6)) AS MedianValue FROM H WHERE 2*Position BETWEEN KnownCount AND KnownCount+2 GROUP BY EventID')],
      'SELECT e.EventID,e.OwnerID,e.MetricValue,COALESCE(m.KnownCount,0) AS PriorKnownCount,m.MedianValue AS PriorMedian,CASE WHEN e.MetricValue>2*m.MedianValue THEN 1 ELSE 0 END AS IsAnomaly FROM E e LEFT JOIN M m ON m.EventID=e.EventID','EventID,OwnerID,MetricValue,PriorKnownCount,PriorMedian,IsAnomaly','OwnerID,EventID','Exclude all same-day peers. An even history needs both central values. No known history or unknown current value means IsAnomaly0.')
    a('Smallest complete tie groups reaching80 percent','Within each segment,total positive analysis values per owner. Select the smallest descending sequence of complete tied-total groups reaching at least80 percent of that segment\'s positive total. Never split a tie. Return selected owners,total,distinct-value rank,whole-peer-group cumulative total and complete segment total.',
      [('T','SELECT Segment,OwnerID,CAST(SUM(MetricValue) AS decimal(28,4)) AS TotalValue FROM E WHERE MetricValue>0 GROUP BY Segment,OwnerID'),('G','SELECT Segment,TotalValue,CAST(SUM(TotalValue) AS decimal(28,4)) AS PeerTotal FROM T GROUP BY Segment,TotalValue'),('C','SELECT *,CAST(SUM(PeerTotal) OVER(PARTITION BY Segment ORDER BY TotalValue DESC ROWS UNBOUNDED PRECEDING) AS decimal(28,4)) AS CumulativeValue,CAST(SUM(PeerTotal) OVER(PARTITION BY Segment) AS decimal(28,4)) AS SegmentTotal,DENSE_RANK() OVER(PARTITION BY Segment ORDER BY TotalValue DESC) AS ValueRank FROM G')],
      'SELECT t.Segment,t.OwnerID,t.TotalValue,c.ValueRank,c.CumulativeValue,c.SegmentTotal FROM T t JOIN C c ON c.Segment=t.Segment AND c.TotalValue=t.TotalValue WHERE c.CumulativeValue-c.PeerTotal<0.8*c.SegmentTotal','Segment,OwnerID,TotalValue,ValueRank,CumulativeValue,SegmentTotal','Segment,ValueRank,OwnerID','When a peer group crosses80 percent,include the whole group. Known zero/negative/unknown values do not contribute to this positive-share report.')
    a('Six-month cohort retention','An owner\'s acquisition month is the first month in its complete eligible activity history. For acquisition cohorts starting in2024,return offsets0..5 with cohort size,distinct active owners in the offset month and retention percentage. Include zero-activity offset months,including2025 where applicable.',
      [('FirstSeen','SELECT OwnerID,DATEFROMPARTS(YEAR(MIN(ActivityDate)),MONTH(MIN(ActivityDate)),1) AS CohortMonth FROM E GROUP BY OwnerID'),('C',"SELECT * FROM FirstSeen WHERE CohortMonth>='20240101' AND CohortMonth<'20250101'"),('N','SELECT 0 AS MonthOffset UNION ALL SELECT MonthOffset+1 FROM N WHERE MonthOffset<5'),('A','SELECT DISTINCT OwnerID,DATEFROMPARTS(YEAR(ActivityDate),MONTH(ActivityDate),1) AS ActivityMonth FROM E')],
      'SELECT c.CohortMonth,n.MonthOffset,DATEADD(month,n.MonthOffset,c.CohortMonth) AS ActivityMonth,COUNT(*) AS CohortSize,COUNT(a.OwnerID) AS ActiveOwners,CAST(100.0*COUNT(a.OwnerID)/COUNT(*) AS decimal(19,6)) AS RetentionPercent FROM C c CROSS JOIN N n LEFT JOIN A a ON a.OwnerID=c.OwnerID AND a.ActivityMonth=DATEADD(month,n.MonthOffset,c.CohortMonth) GROUP BY c.CohortMonth,n.MonthOffset','CohortMonth,MonthOffset,ActivityMonth,CohortSize,ActiveOwners,RetentionPercent','CohortMonth,MonthOffset','Repeated rows or repeated dates cannot multiply an owner. Do not define acquisition from the2024 slice if earlier history exists.')
    a('Longest activity run with one missing day','Deduplicate active dates. For each owner,choose an inclusive start/end interval whose endpoints are active and which contains at most one inactive calendar day in total. Maximize number of active dates;ties choose earliest start then earliest end. Include inactive owners with null dates and zero counts.',
      [('D','SELECT DISTINCT OwnerID,ActivityDate FROM E'),('N','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY ActivityDate) AS Position FROM D'),('C','SELECT s.OwnerID,s.ActivityDate AS StartDate,e.ActivityDate AS EndDate,e.Position-s.Position+1 AS ActiveDays,DATEDIFF(day,s.ActivityDate,e.ActivityDate)+1-(e.Position-s.Position+1) AS MissingDays FROM N s JOIN N e ON e.OwnerID=s.OwnerID AND e.Position>=s.Position WHERE DATEDIFF(day,s.ActivityDate,e.ActivityDate)+1-(e.Position-s.Position+1)<=1'),('R','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY ActiveDays DESC,StartDate,EndDate) AS Choice FROM C')],
      'SELECT o.OwnerID,r.StartDate,r.EndDate,COALESCE(r.ActiveDays,0) AS ActiveDays,COALESCE(r.MissingDays,0) AS MissingDays FROM Owners o LEFT JOIN R r ON r.OwnerID=o.OwnerID AND r.Choice=1','OwnerID,StartDate,EndDate,ActiveDays,MissingDays','OwnerID','Two separate one-day holes violate the budget. Multiple source rows on one day count once.')
    a('Cycle-safe parent resolution','For each analysis row,follow visible parent IDs until a root,a missing/excluded parent,or a repeated ID. Return starting ID,terminal visited ID,root ID only if an actual null-parent root is reached,traversed-edge count,cycle flag,boundary flag and slash-delimited visited path. Do not append the repeated cycle ID.',
      [('Walk',"SELECT EventID AS StartID,EventID AS CurrentID,ParentID AS NextID,CAST('/'+CAST(EventID AS varchar(12))+'/' AS varchar(max)) AS VisitPath,0 AS Depth FROM E UNION ALL SELECT w.StartID,e.EventID,e.ParentID,CAST(w.VisitPath+CAST(e.EventID AS varchar(12))+'/' AS varchar(max)),w.Depth+1 FROM Walk w JOIN E e ON e.EventID=w.NextID WHERE CHARINDEX('/'+CAST(e.EventID AS varchar(12))+'/',w.VisitPath)=0 AND w.Depth<100"),('Terminal',"SELECT w.*,CASE WHEN w.NextID IS NOT NULL AND CHARINDEX('/'+CAST(w.NextID AS varchar(12))+'/',w.VisitPath)>0 THEN 1 ELSE 0 END AS CycleFlag,CASE WHEN w.NextID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM E e WHERE e.EventID=w.NextID) THEN 1 ELSE 0 END AS BoundaryFlag FROM Walk w WHERE w.NextID IS NULL OR CHARINDEX('/'+CAST(w.NextID AS varchar(12))+'/',w.VisitPath)>0 OR NOT EXISTS(SELECT 1 FROM E e WHERE e.EventID=w.NextID)")],
      'SELECT StartID AS EventID,CurrentID AS TerminalEventID,CASE WHEN NextID IS NULL THEN CurrentID END AS RootEventID,Depth,CycleFlag,BoundaryFlag,VisitPath FROM Terminal','EventID,TerminalEventID,RootEventID,Depth,CycleFlag,BoundaryFlag,VisitPath','EventID','The supported chain has at most100 edges. A recursion-limit error is not acceptable cycle detection;IDs1 and11 must not be confused by substring matching.')
    a('As-of correction-chain survivors','For each visible null-parent root,consider all visible descendants including the root. At cutoff2024-12-31,choose the latest candidate date not after cutoff,ties greatest source ID. Return root ID,selected ID,date,value and descendant depth;keep a root with no as-of candidate as null selection. Candidates may branch;one branch must not hide another.',
      [('Versions',"SELECT EventID AS RootID,EventID,ActivityDate,MetricValue,CAST('/'+CAST(EventID AS varchar(12))+'/' AS varchar(max)) AS VisitPath,0 AS Depth FROM E WHERE ParentID IS NULL UNION ALL SELECT v.RootID,e.EventID,e.ActivityDate,e.MetricValue,CAST(v.VisitPath+CAST(e.EventID AS varchar(12))+'/' AS varchar(max)),v.Depth+1 FROM Versions v JOIN E e ON e.ParentID=v.EventID WHERE CHARINDEX('/'+CAST(e.EventID AS varchar(12))+'/',v.VisitPath)=0 AND v.Depth<100"),('R',"SELECT *,ROW_NUMBER() OVER(PARTITION BY RootID ORDER BY ActivityDate DESC,EventID DESC) AS Choice FROM Versions WHERE ActivityDate<='20241231'")],
      'SELECT e.EventID AS RootEventID,r.EventID AS SelectedEventID,r.ActivityDate,r.MetricValue,r.Depth FROM E e LEFT JOIN R r ON r.RootID=e.EventID AND r.Choice=1 WHERE e.ParentID IS NULL','RootEventID,SelectedEventID,ActivityDate,MetricValue,Depth','RootEventID','A newer unknown value remains unknown;do not fall back to an older known value. Rootless cycles are excluded and must be diagnosed by the parent-resolution question.')
    a('FIFO interval allocation','Per owner,treat positive segment-A values as supply and positive segment-B values as demand. Order each stream by date/source ID and allocate FIFO value without requiring supply date<=demand date. Return every positive supply/demand overlap with allocated value,and a row with the other ID null for each unallocated supply or unfilled demand remainder. Ignore all other segments and nonpositive/unknown values.',
      [('Supply','SELECT *,CAST(SUM(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS decimal(28,4)) AS EndValue FROM E WHERE Segment=\'A\' AND MetricValue>0'),('Demand','SELECT *,CAST(SUM(MetricValue) OVER(PARTITION BY OwnerID ORDER BY ActivityDate,EventID ROWS UNBOUNDED PRECEDING) AS decimal(28,4)) AS EndValue FROM E WHERE Segment=\'B\' AND MetricValue>0'),('Matches','SELECT s.OwnerID,s.EventID AS SupplyEventID,d.EventID AS DemandEventID,(CASE WHEN s.EndValue<d.EndValue THEN s.EndValue ELSE d.EndValue END)-(CASE WHEN s.EndValue-s.MetricValue>d.EndValue-d.MetricValue THEN s.EndValue-s.MetricValue ELSE d.EndValue-d.MetricValue END) AS AllocatedValue FROM Supply s JOIN Demand d ON d.OwnerID=s.OwnerID AND s.EndValue>d.EndValue-d.MetricValue AND d.EndValue>s.EndValue-s.MetricValue'),('Result','SELECT OwnerID,SupplyEventID,DemandEventID,AllocatedValue,CAST(0 AS decimal(38,4)) AS UnmatchedValue FROM Matches UNION ALL SELECT s.OwnerID,s.EventID,NULL,0,s.MetricValue-COALESCE(x.UsedValue,0) FROM Supply s LEFT JOIN(SELECT SupplyEventID,CAST(SUM(AllocatedValue) AS decimal(28,4)) AS UsedValue FROM Matches GROUP BY SupplyEventID)x ON x.SupplyEventID=s.EventID WHERE s.MetricValue>COALESCE(x.UsedValue,0) UNION ALL SELECT d.OwnerID,NULL,d.EventID,0,d.MetricValue-COALESCE(x.UsedValue,0) FROM Demand d LEFT JOIN(SELECT DemandEventID,CAST(SUM(AllocatedValue) AS decimal(28,4)) AS UsedValue FROM Matches GROUP BY DemandEventID)x ON x.DemandEventID=d.EventID WHERE d.MetricValue>COALESCE(x.UsedValue,0)')],
      'SELECT OwnerID,SupplyEventID,DemandEventID,AllocatedValue,UnmatchedValue FROM Result','OwnerID,SupplyEventID,DemandEventID,AllocatedValue,UnmatchedValue','OwnerID,SupplyEventID,DemandEventID','A supply may feed several demands and vice versa. Allocation plus unmatched supply/demand must independently conserve both sides. Boundary-touching intervals allocate zero and must not appear.')
    a('Conserved largest-remainder allocation','Within each segment,sum positive values per owner and allocate exactly10000 integer basis points proportionally to owner totals. Floor each ideal share,then give leftover points by greatest fractional remainder,ties owner ID ascending. Return totals,allocated basis points and segment total.',
      [('T','SELECT Segment,OwnerID,CAST(SUM(MetricValue) AS decimal(28,4)) AS TotalValue FROM E WHERE MetricValue>0 GROUP BY Segment,OwnerID'),('W','SELECT *,CAST(SUM(TotalValue) OVER(PARTITION BY Segment) AS decimal(28,4)) AS SegmentTotal FROM T'),('Units','SELECT *,CAST(TotalValue*10000 AS decimal(28,0)) AS TotalUnits,CAST(SegmentTotal*10000 AS decimal(28,0)) AS SegmentUnits FROM W'),('Numerators','SELECT *,CAST(TotalUnits*10000 AS decimal(33,0)) AS NumeratorUnits FROM Units'),('Remainders','SELECT *,NumeratorUnits%SegmentUnits AS RemainderUnits FROM Numerators'),('Bases','SELECT *,CAST((NumeratorUnits-RemainderUnits)/SegmentUnits AS int) AS BasePoints FROM Remainders'),('R','SELECT *,10000-SUM(BasePoints) OVER(PARTITION BY Segment) AS RemainingPoints,ROW_NUMBER() OVER(PARTITION BY Segment ORDER BY RemainderUnits DESC,OwnerID) AS RemainderPosition FROM Bases')],
      'SELECT Segment,OwnerID,TotalValue,BasePoints+CASE WHEN RemainderPosition<=RemainingPoints THEN 1 ELSE 0 END AS BasisPoints,SegmentTotal FROM R','Segment,OwnerID,TotalValue,BasisPoints,SegmentTotal','Segment,OwnerID','Independent rounded percentages need not sum to10000. Compare exact remainders,not ratios rounded before flooring. Input positive totals in one segment are bounded by10^18 and analysis values have at most four fractional digits. Exclude segments with no positive contributions.')
    a('Complete inactivity intervals','For every master owner,return maximal inclusive date intervals without eligible activity inside2024. No daily expansion is allowed in the submitted query. Include Jan1/Dec31 boundaries and the leap day correctly.',
      [('D',"SELECT DISTINCT OwnerID,ActivityDate FROM E WHERE ActivityDate>='20240101' AND ActivityDate<'20250101' UNION SELECT OwnerID,CAST('20231231' AS date) FROM Owners UNION SELECT OwnerID,CAST('20250101' AS date) FROM Owners"),('L','SELECT OwnerID,ActivityDate,LEAD(ActivityDate) OVER(PARTITION BY OwnerID ORDER BY ActivityDate) AS NextDate FROM D')],
      'SELECT OwnerID,DATEADD(day,1,ActivityDate) AS StartDate,DATEADD(day,-1,NextDate) AS EndDate,DATEDIFF(day,ActivityDate,NextDate)-1 AS MissingDays FROM L WHERE DATEDIFF(day,ActivityDate,NextDate)>1','OwnerID,StartDate,EndDate,MissingDays','OwnerID,StartDate','An inactive owner has one366-day interval. Repeated active dates cannot split a gap.')
    a('Ordered three-stage funnel','Find each owner\'s earliest completion of segment A then B then C in strictly increasing(date,source ID) order. Among chains ending at that earliest C,choose latest B,then latest A before that B. Return the three IDs and start/completion dates.',
      [('C','SELECT a.OwnerID,a.EventID AS FirstEventID,b.EventID AS SecondEventID,c.EventID AS ThirdEventID,a.ActivityDate AS StartDate,c.ActivityDate AS EndDate,ROW_NUMBER() OVER(PARTITION BY a.OwnerID ORDER BY c.ActivityDate,c.EventID,b.ActivityDate DESC,b.EventID DESC,a.ActivityDate DESC,a.EventID DESC) AS Choice FROM E a JOIN E b ON b.OwnerID=a.OwnerID AND (b.ActivityDate>a.ActivityDate OR(b.ActivityDate=a.ActivityDate AND b.EventID>a.EventID)) JOIN E c ON c.OwnerID=b.OwnerID AND (c.ActivityDate>b.ActivityDate OR(c.ActivityDate=b.ActivityDate AND c.EventID>b.EventID)) WHERE a.Segment=\'A\' AND b.Segment=\'B\' AND c.Segment=\'C\'')],
      'SELECT OwnerID,FirstEventID,SecondEventID,ThirdEventID,StartDate,EndDate FROM C WHERE Choice=1','OwnerID,FirstEventID,SecondEventID,ThirdEventID,StartDate,EndDate','OwnerID','A,B,C on the same date can qualify only in increasing source-ID order. Do not independently pick each segment\'s earliest row.')
    a('Earliest rolling coverage with witnesses','For each owner,find the earliest eligible activity date on which segments A,B,C all occur in the inclusive30-calendar-day window ending that day. Return that trigger date and the latest(date,source ID) witness for each required segment within that window.',
      [('D','SELECT DISTINCT OwnerID,ActivityDate AS TriggerDate FROM E'),('W','SELECT d.OwnerID,d.TriggerDate,e.Segment,e.EventID,ROW_NUMBER() OVER(PARTITION BY d.OwnerID,d.TriggerDate,e.Segment ORDER BY e.ActivityDate DESC,e.EventID DESC) AS Position FROM D d JOIN E e ON e.OwnerID=d.OwnerID AND e.ActivityDate>=DATEADD(day,-29,d.TriggerDate) AND e.ActivityDate<=d.TriggerDate WHERE e.Segment IN(\'A\',\'B\',\'C\')'),('P','SELECT OwnerID,TriggerDate,MAX(CASE WHEN Segment=\'A\' THEN EventID END) AS AEventID,MAX(CASE WHEN Segment=\'B\' THEN EventID END) AS BEventID,MAX(CASE WHEN Segment=\'C\' THEN EventID END) AS CEventID FROM W WHERE Position=1 GROUP BY OwnerID,TriggerDate HAVING COUNT(*)=3'),('R','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY TriggerDate) AS Choice FROM P')],
      'SELECT OwnerID,TriggerDate,AEventID,BEventID,CEventID FROM R WHERE Choice=1','OwnerID,TriggerDate,AEventID,BEventID,CEventID','OwnerID','The window starts trigger date minus29,not minus30. Unknown-value activity counts;witnesses must come from the same qualifying window.')
    a('Distinct descendant exposure with cycles','For every eligible row,return count and known-value sum of its distinct proper descendants reachable through visible parent links,and whether any reachable path closes a cycle. Exclude the start row itself even when a cycle returns to it. No descendants means count0,total0;descendants all unknown means null total.',
      [('Down','SELECT EventID AS StartID,EventID AS NodeID,CAST(\'/\'+CAST(EventID AS varchar(12))+\'/\' AS varchar(max)) AS VisitPath,0 AS Depth FROM E UNION ALL SELECT d.StartID,e.EventID,CAST(d.VisitPath+CAST(e.EventID AS varchar(12))+\'/\' AS varchar(max)),d.Depth+1 FROM Down d JOIN E e ON e.ParentID=d.NodeID WHERE CHARINDEX(\'/\'+CAST(e.EventID AS varchar(12))+\'/\',d.VisitPath)=0 AND d.Depth<100'),('DistinctNodes','SELECT DISTINCT StartID,NodeID FROM Down WHERE Depth>0'),('T','SELECT d.StartID,COUNT(*) AS DescendantCount,COUNT(e.MetricValue) AS KnownCount,SUM(e.MetricValue) AS TotalValue FROM DistinctNodes d JOIN E e ON e.EventID=d.NodeID GROUP BY d.StartID'),('Cycles','SELECT DISTINCT d.StartID FROM Down d JOIN E e ON e.ParentID=d.NodeID WHERE CHARINDEX(\'/\'+CAST(e.EventID AS varchar(12))+\'/\',d.VisitPath)>0')],
      'SELECT e.EventID,COALESCE(t.DescendantCount,0) AS DescendantCount,COALESCE(t.KnownCount,0) AS KnownCount,CASE WHEN t.StartID IS NULL THEN CAST(0 AS decimal(38,4)) ELSE t.TotalValue END AS TotalValue,CASE WHEN c.StartID IS NULL THEN 0 ELSE 1 END AS CycleFlag FROM E e LEFT JOIN T t ON t.StartID=e.EventID LEFT JOIN Cycles c ON c.StartID=e.EventID','EventID,DescendantCount,KnownCount,TotalValue,CycleFlag','EventID','Do not add the same descendant twice or hide a rootless cycle. Supported paths have at most100 edges.')
    a('Best mean-centered contiguous block','For each owner,let N be its known-value count and T its complete known-value total. Give each known row exact signed score N*analysis value-T;this is a scaled mean-centered score,not a monetary amount. In date/source-ID order,unknown values break the sequence into separate blocks. Select the nonempty contiguous known-row subarray with greatest total score. Ties choose earliest start position then earliest end position. Include owners without known values as null IDs/score and count0.',
      [('OwnerStats','SELECT OwnerID,COUNT(MetricValue) AS KnownCount,SUM(MetricValue) AS KnownTotal FROM E GROUP BY OwnerID'),('N','SELECT e.*,CAST(s.KnownCount AS decimal(4,0))*e.MetricValue-CAST(s.KnownTotal AS decimal(28,4)) AS ScoreValue,ROW_NUMBER() OVER(PARTITION BY e.OwnerID ORDER BY e.ActivityDate,e.EventID) AS Position,SUM(CASE WHEN e.MetricValue IS NULL THEN 1 ELSE 0 END) OVER(PARTITION BY e.OwnerID ORDER BY e.ActivityDate,e.EventID ROWS UNBOUNDED PRECEDING) AS BlockID FROM E e JOIN OwnerStats s ON s.OwnerID=e.OwnerID'),('P','SELECT *,CAST(SUM(ScoreValue) OVER(PARTITION BY OwnerID,BlockID ORDER BY Position ROWS UNBOUNDED PRECEDING) AS decimal(28,4)) AS PrefixValue FROM N WHERE MetricValue IS NOT NULL'),('C','SELECT s.OwnerID,s.EventID AS StartEventID,e.EventID AS EndEventID,s.Position AS StartPosition,e.Position AS EndPosition,e.PrefixValue-s.PrefixValue+s.ScoreValue AS BlockScore,e.Position-s.Position+1 AS EventCount FROM P s JOIN P e ON e.OwnerID=s.OwnerID AND e.BlockID=s.BlockID AND e.Position>=s.Position'),('R','SELECT *,ROW_NUMBER() OVER(PARTITION BY OwnerID ORDER BY BlockScore DESC,StartPosition,EndPosition) AS Choice FROM C')],
      'SELECT o.OwnerID,r.StartEventID,r.EndEventID,r.BlockScore,COALESCE(r.EventCount,0) AS EventCount FROM Owners o LEFT JOIN R r ON r.OwnerID=o.OwnerID AND r.Choice=1','OwnerID,StartEventID,EndEventID,BlockScore,EventCount','OwnerID','Compute N/T over the complete owner,not separately per known block. Even nonnegative stored values can have negative scores. Never choose an empty zero block. Reference cardinality<=1000 rows per owner;explain a scalable prefix-based alternative for larger inputs.')
    # The fifteenth hard recipe is a real five-table reconciliation supplied
    # separately for each domain,not a generic review/benchmark instruction.
    from domain_interview_reconciliation import reconciliation_recipe
    a('Five-table reconciliation','DOMAIN_SPECIFIC',[], '', '', '', '')
    role_titles={'Every required segment','FIFO interval allocation','Ordered three-stage funnel','Earliest rolling coverage with witnesses'}
    for recipe in rows:
        if recipe['title'] not in role_titles:continue
        recipe['task']=recipe['task'].replace('segments','stored category roles').replace('segment','stored category role')
        transformed=[]
        for name,sql in recipe['ctes']:
            sql=sql.replace('e.Segment','e.Kind').replace('a.Segment','a.Kind').replace('b.Segment','b.Kind').replace('c.Segment','c.Kind')
            sql=sql.replace("WHERE Segment='A'","WHERE Kind='A'").replace("WHERE Segment='B'","WHERE Kind='B'")
            if recipe['title']=='Earliest rolling coverage with witnesses' and name=='W':
                sql=sql.replace('d.TriggerDate,e.Kind,e.EventID','d.TriggerDate,e.Kind AS Segment,e.EventID')
            transformed.append((name,sql))
        recipe['ctes']=transformed
        recipe['report']=recipe['report'].replace('e.Segment','e.Kind')
    return rows


def instantiate(model,topic,subtopic,recipe):
    from domain_interview_reconciliation import reconciliation_recipe
    focus=profile(model,topic,subtopic)
    mp=model['map'];fk=mp['PartyID'];pk=mp['RecordID'];cat=mp['Category']
    focus['ctes']=[('FocusRows' if name=='E' else name,q) for name,q in focus['ctes']]
    focus['ctes'].append(('E',f'SELECT x.*,original.[{cat}] AS Kind FROM FocusRows x JOIN {focus["table"]} original ON original.[{pk}]=x.EventID'))
    focus['rule']+=f' For fixed A/B/C sequence,coverage and supply/demand roles,use the original `{cat}` of the analysis row\'s representative source ID,not a transformed text token.'
    # A profile and a business report may naturally use names such as
    # Eligible/Required. Namespace the profile stages before composing SQL.
    import re
    renamed={name:'Focus_'+name for name,_ in focus['ctes'] if name!='E'}
    def namespace(text):
        for old,new in renamed.items():text=re.sub(r'\b'+re.escape(old)+r'\b',new,text)
        return text
    focus['ctes']=[(renamed.get(name,name),namespace(query)) for name,query in focus['ctes']]
    if recipe['task']=='DOMAIN_SPECIFIC':
        recipe={**recipe,**reconciliation_recipe(model)}
    owners=('Owners',f'SELECT [{fk}] AS OwnerID FROM {focus["parent"]}')
    ctes=focus['ctes']+[owners]+recipe['ctes']+[('Report',recipe['report'])]
    assert len({name.lower() for name,_ in ctes})==len(ctes),'Duplicate composed CTE name'
    mapped={'EventID':pk,'OwnerID':fk}
    select=','.join(f'[{x}] AS [{mapped.get(x,x)}]' for x in recipe['columns'])
    order=recipe['order']
    for name,value in mapped.items():
        import re
        order=re.sub(r'\b'+name+r'\b',value,order)
    sql=';WITH '+',\n'.join(f'{name} AS (\n{query}\n)' for name,query in ctes)
    sql+=f'\nSELECT {select} FROM Report ORDER BY {order} OPTION (MAXRECURSION 32767);'
    # Focus evidence is required too;it prevents a correct-looking final
    # aggregate from concealing an incorrect transformation in the subtopic.
    witness=';WITH '+',\n'.join(f'{name} AS (\n{query}\n)' for name,query in focus['ctes'])
    witness+=f'\nSELECT EventID AS [{pk}],OwnerID AS [{fk}],ActivityDate AS AnalysisDate,MetricValue AS AnalysisValue,Segment AS AnalysisSegment,ParentID AS AnalysisParentID,Kind AS AnalysisKind FROM E ORDER BY EventID OPTION (MAXRECURSION 32767);'
    import re
    focus_text='\n'.join(q for _,q in focus['ctes'])
    fact_model=next(t for t in model['tables'] if t['name']==model['base'][0])
    used=[c['name'] for c in fact_model['columns'] if re.search(r'(?<![A-Za-z0-9_])'+re.escape(c['name'])+r'(?![A-Za-z0-9_])',focus_text)]
    actual_source='; '.join(f'{focus["table"]}.[{v}]' for v in used)+f'; {focus["parent"]}.[{fk}]'
    if re.search(r'\bRegion\b',focus_text):
        actual_source+=f'; {focus["parent"]}.[Region]'
    if recipe['title']=='Five-table reconciliation':
        actual_source='; '.join(f'[{model["slug"]}].[{t["name"]}].['+c['name']+']' for t in model['tables'] for c in t['columns'])
    return dict(focus_rule=focus['rule'],sql=sql,witness_sql=witness,
                output=[mapped.get(x,x) for x in recipe['columns']],sort=order,
                task=recipe['task'],edge=recipe['edge'],source_columns=actual_source)
